1	import { canonicalize, sha256 } from './canonicalize.ts';
2	
3	export const WITNESS_REAL_APP_SCHEMA = 'versionless.witness-real-app-interactions.v4' as const;
4	export const WITNESS_REAL_APP_NAMES = [
5		'react-boilerplate',
6		'angular-phonecat',
7		'killedbygoogle',
8		'angular-realworld',
9		'papercups',
10		'react-hospitalrun',
11		'angular-factoriolab',
12		'angular-jira-clone',
13		/**
14		 * The LEGACY-NEXT static-export vertical, named by its pinned version rather
15		 * than by its repository. The corpus already carries `killedbygoogle` for the
16		 * retired derived-state-to-memo cell, and that name stays exactly where it
17		 * is: this is a different migration of a different revision against different
18		 * lanes, and giving it its own versioned name is what keeps the two proofs
19		 * from being read as one.
20		 */
21		'next-killedbygoogle-v3-0-0',
22		/**
23		 * The create-react-app 5 vertical, and the first in the corpus whose browser
24		 * proof runs against a SYNTHETIC dataset rather than the one its archive
25		 * ships. The application's data layer is 561 real contributors' personal
26		 * profiles; the standing ruling keeps every one of them out of the evidence,
27		 * and the application's own corpus-agnostic codegen is what makes the
28		 * substitution possible without touching a line of its source.
29		 */
30		'react-linkfree',
31		/**
32		 * The OLD-VITE-ORIGIN vertical, and the first in the corpus whose origin
33		 * bundler is Vite itself rather than a webpack-era toolchain: Vite 2.9.5 to
34		 * Vite 8.0.16, six majors apart. Its API surface is answered by a frozen
35		 * synthetic same-origin projection, because the application talks to a Go
36		 * backend that is out of the ingested cell entirely.
37		 */
38		'react-memos',
39		/**
40		 * The `.angular-cli.json` band vertical, and the corpus's longest lift:
41		 * Angular 5 to Angular 16.2, eleven majors. It is also the first application
42		 * here whose journey has to hand the page a file and read back a file the
43		 * page produced — it is a browser-only translation-file editor with no
44		 * backend at all — which is why the two opt-in mechanisms below exist.
45		 */
46		'angular-tiny-translator',
47		/**
48		 * The Angular 8 pre-Ivy ViewEngine vertical, and the first application here
49		 * whose production output ships a REAL service worker in both lanes: the era
50		 * build and the migrated build each emit `ngsw-worker.js`, `safety-worker.js`
51		 * and a generated manifest, and the application registers one on every
52		 * production load. Every other worker story in this corpus is an absence or a
53		 * refusal; this one is a registration that succeeds, which is why its schema
54		 * measures the settled state at three checkpoints per lane instead of
55		 * asserting a zero.
56		 *
57		 * It is also the first whose state lives in IndexedDB rather than in local
58		 * storage, and the first with a genuine drag surface since jira-clone — which
59		 * it is deliberately not a member of the closed drag list for, because that
60		 * membership is earned by a measured drag and no journey has driven one.
61		 */
62		'angular-super-productivity',
63	] as const;
64	/** Every named app must contribute two lanes observed twice each. */
65	export const WITNESS_REAL_APP_RUNS = WITNESS_REAL_APP_NAMES.length * 4;
66	
67	/**
68	 * The closed list of applications whose journeys are permitted to record a drag
69	 * gesture. Drag is not a gesture a journey may reach for because it is
70	 * available: it is only honest where the application has a genuine drag surface
71	 * whose settled result can be asserted exactly, so every other application in
72	 * the corpus continues to record drag as not-tested and fails the run if one
73	 * appears.
74	 */
75	export const WITNESS_REAL_APP_DRAG_SURFACES = ['angular-jira-clone'] as const;
76	
77	export type WitnessGesture = 'click' | 'type' | 'press' | 'hover' | 'scroll' | 'drag';
78	export type WitnessServiceWorkerTelemetry = {
79		state: 'ready';
80		registration: {
81			scriptPath: string | null;
82			scope: string | null;
83			installing: string | null;
84			waiting: string | null;
85			active: string | null;
86		};
87		controller: string | null;
88		cacheNames: string[];
89		cacheEntries: Array<{ name: string; paths: string[] }>;
90		workerEvents: Array<
91			| { kind: 'registration'; scopePath: string }
92			| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
93			| {
94					kind: 'error';
95					message: string;
96					sourcePath: string;
97					lineNumber: number;
98					columnNumber: number;
99			  }
100		>;
101	};
102	export type WitnessOfflineEvidence =
103		| {
104				state: 'react-shell-rendered-state-reset';
105				shellRendered: true;
106				usernameReset: true;
107				repositoriesReset: true;
108				apiResponseCaching: 'not-claimed';
109				reduxPersistence: 'not-implemented';
110				priorResultPersistence: 'not-implemented';
111				harnessFulfillment: 'synthetic-github-route-online-only';
112				serviceWorkerEvidence: {
113					source: 'canonical-t060';
114					receiptPath: 'evidence/runs/react-boilerplate-v4-composed/t060-run.json';
115					canonicalDigest: '52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21';
116					newProof: false;
117				};
118				lifecycle: {
119					state: 'ready-online-reload-controlled-offline-reset';
120					ready: WitnessServiceWorkerTelemetry;
121					controlled: WitnessServiceWorkerTelemetry & { controller: 'activated' };
122					onlineStaticPaths: string[];
123					offlineServerRequests: 0;
124				};
125		  }
126		| { state: 'not-applicable' };
127	export type WitnessNextPrerenderPayloadEvidence =
128		| {
129				state: 'exact-lane-bound-next-prerender';
130				lane: 'baseline' | 'migrated';
131				buildId: string;
132				buildIdSha256: string;
133				retainedIndexSha256: string;
134				prerenderManifestSha256: string;
135				dataRoute: string;
136				sourcePath: string;
137				stagedPath: string;
138				payload: {
139					bytes: number;
140					sha256: string;
141					keys: ['__N_SSG', 'pageProps'];
142				};
143				response: {
144					method: 'GET';
145					pathname: string;
146					query: '';
147					destination: 'empty';
148					resolvedFile: string;
149					status: 200;
150					mime: 'application/json';
151					bytes: number;
152					sha256: string;
153				};
154		  }
155		| { state: 'not-applicable' };
156	/**
157	 * Exact, application-scoped accounting for console errors an application emits
158	 * on its own.
159	 *
160	 * A blanket "console errors are allowed" switch would mask regressions, so this
161	 * is deliberately not one: `expected` pins every message text and its exact
162	 * occurrence count, `observed` records what the browser actually reported, and
163	 * `outsideInventory` must stay empty — any error whose text is not already
164	 * pinned fails the run. Origins are normalized because the loopback port is
165	 * ephemeral; everything after the origin is real observed text.
166	 */
167	export type WitnessConsoleErrorInventoryEntry = { message: string; count: number };
168	export type WitnessConsoleErrorInventory = {
169		policy: 'exact-app-scoped-expected-console-errors';
170		originPlaceholder: '{production-static-origin}';
171		expected: WitnessConsoleErrorInventoryEntry[];
172		observed: WitnessConsoleErrorInventoryEntry[];
173		outsideInventory: [];
174		total: number;
175	};
176	
177	/**
178	 * Exact, application-scoped accounting for requests the browser itself failed,
179	 * held to the same discipline as the console-error inventory: every expected
180	 * failure is pinned by origin-relative path, method and reason with its exact
181	 * count, and any failure outside the pinned set fails the run. Paths are
182	 * origin-relative because the loopback port is ephemeral.
183	 */
184	export type WitnessFailedRequestInventoryEntry = {
185		method: string;
186		path: string;
187		/** The browser's own failure reason, or null when the driver reported none. */
188		reason: string | null;
189		count: number;
190	};
191	export type WitnessFailedRequestInventory = {
192		policy: 'exact-app-scoped-expected-failed-requests';
193		expected: WitnessFailedRequestInventoryEntry[];
194		observed: WitnessFailedRequestInventoryEntry[];
195		outsideInventory: [];
196		total: number;
197	};
198	
199	/**
200	 * The exact rule that admits a member of the cancelled-duplicate-fetch
201	 * category, carried in the receipt so a reader checks the rule rather than
202	 * trusting the label. It is stated once here and copied into every inventory,
203	 * so a receipt cannot quietly describe a weaker rule than the one the
204	 * mechanism enforced.
205	 */
206	export const WITNESS_CANCELLED_DUPLICATE_FETCH_RULE =
207		'A browser-cancelled fetch is admitted only when the same page also fetched the same origin-relative path with the same method successfully at least once during the same run. A cancelled fetch with no successful sibling is not admitted and fails the run as an ordinary failed request.' as const;
208	
209	/**
210	 * How a request outside the bounded loopback origin is written down.
211	 *
212	 * A seam the harness answers inside the browser context is still a request the
213	 * application made, and it belongs in the evidence. What does not belong is the
214	 * query string: for the analytics and error-reporting endpoints applications of
215	 * this era reach for, the query is exactly where the account identifier lives —
216	 * a measurement id, a DSN public key — and copying it into a published receipt
217	 * would publish a credential nobody asked to publish. So the recorded path for
218	 * a non-loopback request is query-free by construction: scheme, host and
219	 * pathname, and nothing after them. Nothing is lost that identifies the seam,
220	 * because the seam is the endpoint, not the account calling it.
221	 *
222	 * Same-origin loopback paths are untouched by this and stay exactly as the
223	 * browser requested them, query included: the loopback origin is the harness's
224	 * own, it mints no credentials, and its query strings are part of what a
225	 * production-static claim is about.
226	 */
227	export const WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE =
228		'A request outside the bounded loopback origin is recorded by scheme, host and pathname only. The query string is never recorded, because for these endpoints it carries the account identifier rather than the identity of the seam. Same-origin loopback paths are recorded exactly as requested, query included.' as const;
229	
230	/**
231	 * The extension of the cancelled-duplicate-fetch category to seams the harness
232	 * answers inside the browser context rather than over the network.
233	 *
234	 * The generic rule is unchanged and unweakened — a cancelled fetch is admitted
235	 * only when the same page fetched the same method and path successfully at
236	 * least once in the same run. What this states is that "successfully" means the
237	 * response the page actually received, whether it came from the bounded
238	 * loopback origin or from the harness answering a mocked seam in-context. A
239	 * navigation that aborts an in-flight report of a seam the same page already
240	 * reported to twice is the same race the category was built for, and it is
241	 * recorded as the category rather than pinned to a count the page's load timing
242	 * decides.
243	 */
244	export const WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE =
245		'The corroboration rule is applied unchanged to mocked non-loopback seams: the corroborating success is the 2xx response the page received, whether the bounded loopback origin or the in-context harness produced it. Members whose path is not loopback are pinned query-free, so no member can encode an account identifier.' as const;
246	
247	/**
248	 * One member of the cancelled-duplicate-fetch category, pinned by
249	 * recorded path, method and the browser's own cancellation reason.
250	 *
251	 * Deliberately no count. This category exists for one measured browser
252	 * behavior: a page fetches an asset, re-renders while that fetch is in flight,
253	 * starts an identical fetch, and the browser cancels one of the two. Which of
254	 * them the browser cancels, and how many times it happens in a given run, is
255	 * scheduling — pinning a count would pin a race. What is pinned instead is the
256	 * identity of the request that may be cancelled, and admission still requires
257	 * the corroboration below on every single instance.
258	 */
259	export type WitnessCancelledDuplicateFetchCategoryEntry = {
260		method: string;
261		path: string;
262		/** The browser's own cancellation reason, matched exactly. */
263		reason: string;
264	};
265	
266	/**
267	 * One admitted instance, recorded with the corroboration that admitted it, so
268	 * the receipt shows the evidence rather than the verdict. `cancelled` is the
269	 * number of times this exact fetch was cancelled in this run;
270	 * `corroboratingSuccesses` is the number of times the same page fetched the
271	 * same path and method successfully, and must be at least one.
272	 */
273	export type WitnessCancelledDuplicateFetchInstance = WitnessCancelledDuplicateFetchCategoryEntry & {
274		cancelled: number;
275		corroboratingSuccesses: number;
276		/** The distinct response statuses of those successful fetches, ascending. */
277		corroboratingStatuses: number[];
278	};
279	
280	/**
281	 * Accounting for the cancelled-duplicate-fetch category. This is a category,
282	 * not an allowance: it removes nothing from the evidence, it re-files a named
283	 * and corroborated browser behavior into its own inventory where every instance
284	 * is recorded individually. Every other failed request continues through the
285	 * exact {@link WitnessFailedRequestInventory} and still fails the run, and a
286	 * cancelled fetch that matches `category` but finds no successful sibling is
287	 * left in that inventory too — which is to say it fails.
288	 *
289	 * `absent` records category members this run never observed, because the whole
290	 * point of the category is that the behavior is intermittent: a run that did
291	 * not race is recorded as not having raced rather than silently indistinguishable
292	 * from one that did. `uncorroborated` must stay empty by construction.
293	 */
294	export type WitnessCancelledDuplicateFetchInventory = {
295		policy: 'corroborated-browser-cancelled-duplicate-fetch';
296		corroborationRule: typeof WITNESS_CANCELLED_DUPLICATE_FETCH_RULE;
297		category: WitnessCancelledDuplicateFetchCategoryEntry[];
298		observed: WitnessCancelledDuplicateFetchInstance[];
299		absent: WitnessCancelledDuplicateFetchCategoryEntry[];
300		uncorroborated: [];
301		/** Cancelled fetches admitted by the category in this run, summed. */
302		admitted: number;
303		/**
304		 * Present exactly when the category declares a member outside the loopback
305		 * origin, and carrying the scope statement that governs those members. A run
306		 * whose category is entirely same-origin omits it, so an application that
307		 * never reached past loopback cannot be read as having claimed anything about
308		 * seams it does not have.
309		 */
310		nonLoopbackScope?: typeof WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE;
311	};
312	
313	/**
314	 * One non-loopback seam the application reaches for and the harness answers
315	 * inside the browser context, pinned by method and query-free recorded path.
316	 *
317	 * This is an inventory, not an allowance: the point of naming every seam is
318	 * that a request to an endpoint nobody declared fails the run rather than being
319	 * absorbed into a total. Nothing here is a successful non-loopback request —
320	 * none of these left the machine — which is why `successfulNonLoopback` stays
321	 * zero alongside it.
322	 */
323	export type WitnessMockedNonLoopbackSeamEntry = { method: string; path: string };
324	
325	/**
326	 * One declared seam as this run actually observed it. `requests` is recorded
327	 * rather than pinned, because how many times a page reports to an analytics or
328	 * error endpoint is load timing; the statuses are the answers the harness gave.
329	 */
330	export type WitnessMockedNonLoopbackSeamObservation = WitnessMockedNonLoopbackSeamEntry & {
331		requests: number;
332		/** The distinct statuses the harness answered with, ascending. */
333		statuses: number[];
334	};
335	
336	/**
337	 * Exact, application-scoped accounting for the seams an application reaches for
338	 * outside loopback, held to the same non-masking discipline as the console and
339	 * failed-request inventories: every declared member is either observed or
340	 * explicitly absent, and anything observed outside the declared membership is
341	 * reported by its own path and fails the run.
342	 */
343	export type WitnessMockedNonLoopbackSeamInventory = {
344		policy: 'exact-app-scoped-mocked-non-loopback-seams';
345		pathPolicy: typeof WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE;
346		category: WitnessMockedNonLoopbackSeamEntry[];
347		observed: WitnessMockedNonLoopbackSeamObservation[];
348		absent: WitnessMockedNonLoopbackSeamEntry[];
349		outsideInventory: [];
350		/** None of these left the machine; the harness answered every one in-context. */
351		successfulNonLoopback: 0;
352	};
353	
354	/**
355	 * Resolved appearance measured from the live page for a closed list of probes.
356	 *
357	 * A claim that two lanes render the same has to be measured on laid-out
358	 * elements, not inferred from the stylesheet bytes that were shipped — an
359	 * application whose migration replaced a narrow style entry point with an
360	 * aggregate ships different bytes on purpose, and the only honest way to say
361	 * the difference is invisible is to read what the browser resolved.
362	 */
363	export type WitnessRenderedStyleMeasurement = {
364		label: string;
365		selector: string;
366		width: number;
367		height: number;
368		properties: Record<string, string>;
369	};
370	export type WitnessRenderedStyleEvidence = {
371		state: 'measured-resolved-styles';
372		probes: WitnessRenderedStyleMeasurement[];
373	};
374	
375	/**
376	 * The exact rule that governs handing a file to a page, carried in the receipt
377	 * so a reader checks the rule rather than trusting the label.
378	 *
379	 * The mechanism is an opt-in and not a capability journeys may reach for: the
380	 * application declares the surface — the selector, and the fixture that is
381	 * loaded into it — and the harness loads exactly that. An application that
382	 * declares no file-input surface is run without the mechanism at all, so the
383	 * eleven verticals that never asked for it cannot have been changed by it.
384	 */
385	export const WITNESS_FILE_INPUT_LOAD_RULE =
386		'A file is handed to a page only through a surface the application itself declared, by selector and by fixture. The harness loads that fixture and no other, and records the bytes it handed over by file name, byte length and sha256. An application that declares no file-input surface has no way to load one.' as const;
387	
388	/**
389	 * The exact rule that governs reading back a file a page produced.
390	 *
391	 * Accepting downloads is a browser-context capability, and granting it to an
392	 * application that never claimed to produce one would mean a download could
393	 * succeed unobserved. So it is granted only where the application declares it,
394	 * and where it is granted every download is read back rather than counted:
395	 * suggested filename, byte length and sha256 of the bytes the browser wrote.
396	 */
397	export const WITNESS_DOWNLOAD_CAPTURE_RULE =
398		'A browser context accepts downloads only where the application declared that it produces them. Where it did, every download the page produced is read back by suggested filename, byte length and sha256 and ledgered individually. An application that declared none runs in a context that refuses downloads, so one it never claimed to produce cannot succeed unobserved.' as const;
399	
400	/** One file-input surface an application declared, by selector and fixture. */
401	export type WitnessFileInputSurfaceEntry = {
402		label: string;
403		selector: string;
404		/**
405		 * The fixture as declared: a repository-relative path, never a host-specific
406		 * absolute one, so the evidence names the file rather than the machine.
407		 */
408		fixturePath: string;
409	};
410	
411	/** One load as it happened, recorded from the exact bytes handed to the page. */
412	export type WitnessFileInputLoadEntry = WitnessFileInputSurfaceEntry & {
413		/** The name the page's own `File` object carries. */
414		fileName: string;
415		bytes: number;
416		sha256: string;
417	};
418	
419	/**
420	 * Accounting for the file-input mechanism, held to the same non-masking
421	 * discipline as the other inventories: every declared surface is either loaded
422	 * or explicitly unused, and `outsideDeclaration` must stay empty by
423	 * construction — a load through a surface nobody declared is impossible to
424	 * reach and fails the run if it is ever recorded.
425	 */
426	export type WitnessFileInputLoadInventory = {
427		policy: 'declared-file-input-surfaces-only';
428		rule: typeof WITNESS_FILE_INPUT_LOAD_RULE;
429		declared: WitnessFileInputSurfaceEntry[];
430		loaded: WitnessFileInputLoadEntry[];
431		unused: WitnessFileInputSurfaceEntry[];
432		outsideDeclaration: [];
433	};
434	
435	/** One download as the browser wrote it, read back rather than counted. */
436	export type WitnessCapturedDownloadEntry = {
437		suggestedFilename: string;
438		bytes: number;
439		sha256: string;
440	};
441	
442	/**
443	 * Accounting for the download-capture mechanism. `acceptDownloads` records the
444	 * browser-context capability this run was granted, so a reader can see that the
445	 * capability and the evidence came from the same declaration.
446	 */
447	export type WitnessDownloadCaptureInventory = {
448		policy: 'declared-download-surface-only';
449		rule: typeof WITNESS_DOWNLOAD_CAPTURE_RULE;
450		acceptDownloads: true;
451		captured: WitnessCapturedDownloadEntry[];
452	};
453	
454	/**
455	 * Measured journey facts that only one application's own surfaces can express —
456	 * the settled state of a board after a drag, the counts a filter narrowed to,
457	 * the text a tooltip rendered.
458	 *
459	 * The generic runner carries this without inspecting it, which is deliberate:
460	 * inventing a shared vocabulary for facts that are not shared would either
461	 * flatten them into something unfalsifiable or push one application's nouns
462	 * into everyone else's schema. The strictness is not lost, it moves — the
463	 * application's own receipt schema narrows this to an exact shape and checks
464	 * every field of it, and because the whole record participates in that
465	 * application's behavior digest, a lane that measured something different
466	 * cannot agree with its own pair.
467	 */
468	export type WitnessApplicationJourneyEvidence = Record<string, unknown>;
469	
470	/**
471	 * One observed service-worker-script event, stripped of the two fields that
472	 * cannot reproduce: the wall-clock timestamp and the run-global sequence
473	 * number, which counts every other asset the lane happens to load. What
474	 * remains — who observed it, in what phase, for which path, with what detail —
475	 * is the substance of the observation and is identical run to run.
476	 */
477	export type WitnessServiceWorkerRequestEvent = {
478		source: string;
479		phase: string;
480		urlPath: string | null;
481		detail: Record<string, boolean | number | string | null>;
482	};
483	/** The same event with the number of times it was observed, for exact accounting. */
484	export type WitnessServiceWorkerRequestTally = WitnessServiceWorkerRequestEvent & {
485		count: number;
486	};
487	
488	/**
489	 * One phased reading of a service worker that is genuinely running.
490	 *
491	 * The phases are the journey's own three moments — before it touches anything,
492	 * after it has, and after a reload that put the page back on the network — so a
493	 * worker that only looks installed at one of them cannot pass for one that
494	 * survived the journey.
495	 */
496	export type WitnessRealServiceWorkerCheckpoint = {
497		phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
498		telemetry: WitnessServiceWorkerTelemetry;
499	};
500	
501	/**
502	 * A lane whose service-worker registration SUCCEEDS, which until now no shape in
503	 * this corpus could record.
504	 *
505	 * Every existing worker shape is a shape of absence: an application that never
506	 * asks, one whose registration the context refuses, one whose legacy build emits
507	 * a script it unregisters. Each of those asserts an empty settled state, so none
508	 * of them can carry a worker that installed, activated and took control — the
509	 * assertions that make them strong are exactly the assertions such a lane would
510	 * fail. This is the additive fourth member, and it is strong in the opposite
511	 * direction: the settled state is recorded rather than required to be empty, the
512	 * worker scripts the build shipped are read from the served tree before and
513	 * after the run and must be byte-identical, and the observer's own trace may not
514	 * be empty, because a browser that registered a worker recorded doing so.
515	 */
516	export type WitnessRealServiceWorkerEvidence = {
517		/** The script the application asked the browser to register. */
518		script: string;
519		checkpoints: WitnessRealServiceWorkerCheckpoint[];
520		/** The worker scripts the build emitted, read from the served tree either side of the run. */
521		outputFiles: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
522		workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
523	};
524	
525	/** The three phases, in the order a journey reaches them. */
526	export const WITNESS_REAL_SERVICE_WORKER_PHASES = [
527		'before-interactions',
528		'after-interactions',
529		'after-online-reload',
530	] as const;
531	
532	export type WitnessRealAppRun = {
533		app: (typeof WITNESS_REAL_APP_NAMES)[number];
534		framework: 'react' | 'angularjs' | 'next' | 'angular';
535		lane: 'baseline' | 'migrated';
536		pass: 1 | 2;
537		result: 'pass';
538		interactions: Array<{ kind: WitnessGesture; selector: string }>;
539		assertions: string[];
540		routes: string[];
541		trackedEvents: string[];
542		witnessRecord: {
543			interactions: Array<{ kind: WitnessGesture; selector: string }>;
544			navigationPaths: string[];
545			trackedEventCounts: Record<string, number>;
546			consoleErrors: number;
547			pageErrors: number;
548			/**
549			 * Requests the browser failed, excluding the ones admitted by this run's
550			 * cancelled-duplicate-fetch category, which are recorded instance by
551			 * instance in {@link WitnessRealAppRun.cancelledDuplicateFetches}. A run
552			 * that declares no such category — every application here but the ones
553			 * that measured the behavior — has nothing to exclude, so this stays the
554			 * total number of browser-failed requests it has always been.
555			 */
556			failedRequests: number;
557		};
558		cleanPage: true;
559		offlineEvidence: WitnessOfflineEvidence;
560		servedStatic: {
561			transport: 'isolated-bounded-loopback-production-static';
562			documentFallback: 'index-only';
563			missingAssets: '404';
564			traversal: 'rejected';
565			inventory: { files: number; beforeSha256: string; afterSha256: string };
566			application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
567			serviceWorkers: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
568			byteIdentical: true;
569			hmrControls: false;
570			legacyMainPrecache:
571				| {
572						state: 'exact-completed';
573						responses: Array<{
574							method: 'GET';
575							pathname: string;
576							query: '?__uncache=versionless-deterministic';
577							destination: 'empty';
578							resolvedFile: string;
579							status: 200;
580							mime: string;
581							bytes: number;
582							sha256: string;
583							urlPath: string;
584							source: 'production-static-origin';
585						}>;
586				  }
587				| { state: 'not-applicable' };
588			phonecatOrdering:
589				| {
590						state: 'data-derived-full-order';
591						datasetSha256: string;
592						orderSha256: string;
593						rows: 20;
594						comparator: 'stable-lowercase-utf16-source-order-ties';
595				  }
596				| { state: 'not-applicable' };
597			phonecatImageTransition:
598				| {
599						state: 'data-derived-visible-transition';
600						detailSha256: string;
601						defaultImage: string;
602						nonDefaultImage: string;
603						hover: 'genuine-thumbnail-mouseover';
604						transition: 'genuine-ng-click';
605						heroVisibility: 'genuine-hover';
606				  }
607				| { state: 'not-applicable' };
608			nextPrerenderPayload?: WitnessNextPrerenderPayloadEvidence;
609		};
610		observerFinalization: {
611			state: 'target-closed';
612			detach: 'owned-detach-complete';
613			pageClose: 'owned-page-close-complete';
614			workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
615		};
616		semanticDigest: string;
617		successfulNonLoopback: 0;
618		consoleErrorInventory?: WitnessConsoleErrorInventory;
619		failedRequestInventory?: WitnessFailedRequestInventory;
620		cancelledDuplicateFetches?: WitnessCancelledDuplicateFetchInventory;
621		mockedNonLoopbackSeams?: WitnessMockedNonLoopbackSeamInventory;
622		/**
623		 * Present exactly when the application declared a file-input surface. Its
624		 * absence is the evidence that this run's page was never handed a file.
625		 */
626		fileInputLoads?: WitnessFileInputLoadInventory;
627		/**
628		 * Present exactly when the application declared that it produces downloads.
629		 * Its absence is the evidence that this run's browser context refused them.
630		 */
631		downloadCaptures?: WitnessDownloadCaptureInventory;
632		renderedStyles?: WitnessRenderedStyleEvidence;
633		applicationJourney?: WitnessApplicationJourneyEvidence;
634		scrollSurface?: WitnessScrollSurface;
635		scrollAbsence?: WitnessMeasuredScrollAbsence;
636	};
637	
638	/**
639	 * Measured scroll evidence for one route that genuinely overflows the stated
640	 * viewport. The document extents are read from the live page, and the scroll
641	 * itself is a real wheel gesture the browser driver confirms moved the
642	 * viewport — the boolean is an observation, not a claim substituted for one.
643	 */
644	export type WitnessScrollSurface = {
645		state: 'measured-genuine-viewport-scroll';
646		route: string;
647		viewport: { width: number; height: number };
648		scrollHeight: number;
649		clientHeight: number;
650		wheelDeltaY: number;
651		scrolledFromTop: true;
652		scrolled: true;
653	};
654	
655	/**
656	 * The measured counterpart of {@link WitnessScrollSurface}: evidence that a
657	 * journey looked for a scroll surface and did not find one.
658	 *
659	 * An application that pins its document to the viewport and scrolls its own
660	 * inner panels instead has no scrollable document to gesture at, and inventing
661	 * one would be a false claim. So the same generic measurement that backs a
662	 * scroll claim is taken at every visited route and recorded here instead:
663	 * `scrollHeight` never exceeds `clientHeight`, which is why no scroll coverage
664	 * is claimed. Routes are recorded individually rather than summarized, so a
665	 * route that starts overflowing later cannot hide inside a total.
666	 */
667	export type WitnessMeasuredScrollAbsence = {
668		state: 'measured-no-overflowing-document';
669		viewport: { width: number; height: number };
670		routes: Array<{ route: string; scrollHeight: number; clientHeight: number }>;
671		/** How the application keeps the document from overflowing, observed rather than assumed. */
672		documentOverflow: string;
673		claimed: false;
674	};
675	
676	export type WitnessMutationProof = {
677		app: 'react-boilerplate' | 'angular-realworld';
678		failure: 'witness-semantic-assertion';
679		intendedFailure: true;
680		restoredByteIdentically: true;
681	};
682	
683	export type WitnessRealAppReceipt = {
684		schemaVersion: typeof WITNESS_REAL_APP_SCHEMA;
685		result: 'pass';
686		provenance: Record<string, unknown>;
687		canonicalReceipts: Array<{
688			app: string;
689			path: string;
690			sha256: string;
691			canonicalDigest: string;
692		}>;
693		runs: WitnessRealAppRun[];
694		mutations: WitnessMutationProof[];
695		killedByGoogleInventory: {
696			archiveSha256: string;
697			mirrorFiles: number;
698			sourceFiles: Record<'baseline' | 'migrated', number>;
699			buildFiles: Record<'baseline' | 'migrated', number>;
700			transformEdits: 3;
701		};
702		locality: { mode: 'offline'; successfulNonLoopback: 0; osWideIsolation: false };
703		nonclaims: string[];
704		integrity: { algorithm: 'sha256'; canonicalDigest: string };
705	};
706	
707	function record(value: unknown, label: string): Record<string, unknown> {
708		if (value === null || typeof value !== 'object' || Array.isArray(value))
709			throw new Error(`Witness real-app ${label} must be an object`);
710		return value as Record<string, unknown>;
711	}
712	
713	function sha256Digest(value: unknown): value is string {
714		return typeof value === 'string' && value.length === 64;
715	}
716	
717	function sortedUniqueStrings(values: unknown): values is string[] {
718		return (
719			Array.isArray(values) &&
720			values.every((value) => typeof value === 'string') &&
721			new Set(values).size === values.length &&
722			values.join('\n') === [...values].sort().join('\n')
723		);
724	}
725	
726	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
727		const telemetry = value as WitnessServiceWorkerTelemetry;
728		return (
729			telemetry?.state === 'ready' &&
730			telemetry.registration?.scriptPath === '/sw.js' &&
731			telemetry.registration.scope === '/' &&
732			telemetry.registration.active === 'activated' &&
733			(telemetry.controller === 'activated' || telemetry.controller === null) &&
734			sortedUniqueStrings(telemetry.cacheNames) &&
735			telemetry.cacheNames.length === 1 &&
736			Array.isArray(telemetry.cacheEntries) &&
737			telemetry.cacheEntries.length === 1 &&
738			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
739			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
740			telemetry.cacheEntries[0].paths.length > 0 &&
741			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
742			Array.isArray(telemetry.workerEvents)
743		);
744	}
745	
746	export function witnessRealAppDigest(receipt: WitnessRealAppReceipt): string {
747		const copy = structuredClone(receipt);
748		copy.integrity.canonicalDigest = '';
749		return sha256(canonicalize(copy));
750	}
751	
752	export function parseWitnessRealAppReceipt(value: unknown): WitnessRealAppReceipt {
753		const receipt = record(value, 'receipt') as WitnessRealAppReceipt;
754		if (
755			receipt.schemaVersion !== WITNESS_REAL_APP_SCHEMA ||
756			receipt.result !== 'pass' ||
757			!Array.isArray(receipt.runs) ||
758			receipt.runs.length !== WITNESS_REAL_APP_RUNS ||
759			!Array.isArray(receipt.canonicalReceipts) ||
760			receipt.canonicalReceipts.length !== WITNESS_REAL_APP_NAMES.length
761		)
762			throw new Error('Witness real-app receipt cardinality differs');
763		const expected = new Set<string>();
764		for (const app of WITNESS_REAL_APP_NAMES)
765			for (const lane of ['baseline', 'migrated'])
766				for (const pass of [1, 2]) expected.add(`${app}:${lane}:${pass}`);
767		const gestures = new Set<WitnessGesture>();
768		const semanticPasses = new Map<string, string>();
769		for (const run of receipt.runs) {
770			const key = `${run.app}:${run.lane}:${run.pass}`;
771			const served = run.servedStatic;
772			const servedStaticDiffers =
773				served?.transport !== 'isolated-bounded-loopback-production-static' ||
774				served.documentFallback !== 'index-only' ||
775				served.missingAssets !== '404' ||
776				served.traversal !== 'rejected' ||
777				!Number.isInteger(served.inventory?.files) ||
778				served.inventory.files < 1 ||
779				!sha256Digest(served.inventory.beforeSha256) ||
780				served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
781				served.application?.path !== 'index.html' ||
782				!sha256Digest(served.application.beforeSha256) ||
783				served.application.beforeSha256 !== served.application.afterSha256 ||
784				!Array.isArray(served.serviceWorkers) ||
785				served.serviceWorkers.some(
786					(serviceWorker) =>
787						serviceWorker.path !== 'sw.js' ||
788						!sha256Digest(serviceWorker.beforeSha256) ||
789						serviceWorker.beforeSha256 !== serviceWorker.afterSha256,
790				) ||
791				(run.app === 'react-boilerplate'
792					? served.serviceWorkers.length !== 1
793					: served.serviceWorkers.length !== 0) ||
794				served.byteIdentical !== true ||
795				served.hmrControls !== false;
796			const expectedLegacyMain = [
797				['/favicon.ico', 'favicon.ico', 'image/x-icon'],
798				[
799					'/2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
800					'2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
801					'image/jpeg',
802				],
803				[
804					'/runtime.bfb7866e5bd316b6a048.js',
805					'runtime.bfb7866e5bd316b6a048.js',
806					'text/javascript',
807				],
808				['/', 'index.html', 'text/html'],
809			] as const;
810			const legacyMainPrecacheDiffers =
811				run.app === 'react-boilerplate' && run.lane === 'baseline'
812					? served.legacyMainPrecache?.state !== 'exact-completed' ||
813						served.legacyMainPrecache.responses.length !== expectedLegacyMain.length ||
814						served.legacyMainPrecache.responses.some((response, index) => {
815							const expectedResponse = expectedLegacyMain[index];
816							return (
817								expectedResponse === undefined ||
818								response.method !== 'GET' ||
819								response.pathname !== expectedResponse[0] ||
820								response.query !== '?__uncache=versionless-deterministic' ||
821								response.destination !== 'empty' ||
822								response.resolvedFile !== expectedResponse[1] ||
823								response.status !== 200 ||
824								response.mime !== expectedResponse[2] ||
825								!Number.isInteger(response.bytes) ||
826								response.bytes < 1 ||
827								!sha256Digest(response.sha256) ||
828								response.urlPath !== `${response.pathname}${response.query}` ||
829								response.source !== 'production-static-origin'
830							);
831						})
832					: served.legacyMainPrecache?.state !== 'not-applicable';
833			const phonecatOrderingDiffers =
834				run.app === 'angular-phonecat'
835					? served.phonecatOrdering?.state !== 'data-derived-full-order' ||
836						!sha256Digest(served.phonecatOrdering.datasetSha256) ||
837						!sha256Digest(served.phonecatOrdering.orderSha256) ||
838						served.phonecatOrdering.rows !== 20 ||
839						served.phonecatOrdering.comparator !==
840							'stable-lowercase-utf16-source-order-ties'
841					: served.phonecatOrdering?.state !== 'not-applicable';
842			const phonecatImageTransitionDiffers =
843				run.app === 'angular-phonecat'
844					? served.phonecatImageTransition?.state !== 'data-derived-visible-transition' ||
845						!sha256Digest(served.phonecatImageTransition.detailSha256) ||
846						!served.phonecatImageTransition.defaultImage.startsWith('img/phones/') ||
847						!served.phonecatImageTransition.nonDefaultImage.startsWith('img/phones/') ||
848						served.phonecatImageTransition.defaultImage ===
849							served.phonecatImageTransition.nonDefaultImage ||
850						served.phonecatImageTransition.hover !== 'genuine-thumbnail-mouseover' ||
851						served.phonecatImageTransition.transition !== 'genuine-ng-click' ||
852						served.phonecatImageTransition.heroVisibility !== 'genuine-hover'
853					: served.phonecatImageTransition?.state !== 'not-applicable';
854			const observerFinalizationDiffers =
855				run.observerFinalization?.state !== 'target-closed' ||
856				run.observerFinalization.detach !== 'owned-detach-complete' ||
857				run.observerFinalization.pageClose !== 'owned-page-close-complete' ||
858				!Array.isArray(run.observerFinalization.workerEvents);
859			const lifecycle =
860				run.offlineEvidence.state === 'react-shell-rendered-state-reset'
861					? run.offlineEvidence.lifecycle
862					: undefined;
863			const expectedCacheName =
864				run.lane === 'baseline'
865					? 'webpack-offline:versionless-deterministic'
866					: 'versionless-react-vite8-553cd1cc611a0851b1978bbc041ef2f8c7b9fbbd3fdd9bb68274f29364987cdc';
867			const lifecycleDiffers =
868				run.app === 'react-boilerplate'
869					? lifecycle?.state !== 'ready-online-reload-controlled-offline-reset' ||
870						!validServiceWorkerTelemetry(lifecycle.ready) ||
871						!validServiceWorkerTelemetry(lifecycle.controlled) ||
872						lifecycle.controlled.controller !== 'activated' ||
873						lifecycle.ready.cacheNames[0] !== expectedCacheName ||
874						canonicalize(lifecycle.ready.cacheEntries) !==
875							canonicalize(lifecycle.controlled.cacheEntries) ||
876						!sortedUniqueStrings(lifecycle.onlineStaticPaths) ||
877						!lifecycle.onlineStaticPaths.includes('/sw.js') ||
878						lifecycle.ready.cacheEntries[0]!.paths.some(
879							(path) =>
880								path !== '/__offline_webpack__data' &&
881								!lifecycle.onlineStaticPaths.includes(path),
882						) ||
883						lifecycle.offlineServerRequests !== 0
884					: lifecycle !== undefined;
885			if (
886				run.interactions.some((interaction) => interaction.kind === 'drag') &&
887				!(WITNESS_REAL_APP_DRAG_SURFACES as readonly string[]).includes(run.app)
888			)
889				throw new Error('Witness real-app drag must remain not-tested');
890			if (
891				!expected.delete(key) ||
892				run.result !== 'pass' ||
893				run.successfulNonLoopback !== 0 ||
894				!Array.isArray(run.interactions) ||
895				run.interactions.length === 0 ||
896				!Array.isArray(run.assertions) ||
897				run.assertions.length === 0 ||
898				servedStaticDiffers ||
899				legacyMainPrecacheDiffers ||
900				phonecatOrderingDiffers ||
901				phonecatImageTransitionDiffers ||
902				observerFinalizationDiffers ||
903				lifecycleDiffers ||
904				run.cleanPage !== true ||
905				(run.app === 'react-boilerplate'
906					? run.offlineEvidence?.state !== 'react-shell-rendered-state-reset' ||
907						run.offlineEvidence.shellRendered !== true ||
908						run.offlineEvidence.usernameReset !== true ||
909						run.offlineEvidence.repositoriesReset !== true ||
910						run.offlineEvidence.apiResponseCaching !== 'not-claimed' ||
911						run.offlineEvidence.reduxPersistence !== 'not-implemented' ||
912						run.offlineEvidence.priorResultPersistence !== 'not-implemented' ||
913						run.offlineEvidence.harnessFulfillment !==
914							'synthetic-github-route-online-only' ||
915						run.offlineEvidence.serviceWorkerEvidence?.source !== 'canonical-t060' ||
916						run.offlineEvidence.serviceWorkerEvidence.receiptPath !==
917							'evidence/runs/react-boilerplate-v4-composed/t060-run.json' ||
918						run.offlineEvidence.serviceWorkerEvidence.canonicalDigest !==
919							'52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21' ||
920						run.offlineEvidence.serviceWorkerEvidence.newProof !== false
921					: run.offlineEvidence?.state !== 'not-applicable') ||
922				run.semanticDigest !==
923					sha256(
924						canonicalize({
925							app: run.app,
926							framework: run.framework,
927							lane: run.lane,
928							interactions: run.interactions,
929							assertions: run.assertions,
930							routes: run.routes,
931							trackedEvents: run.trackedEvents,
932							witnessRecord: run.witnessRecord,
933							cleanPage: run.cleanPage,
934							offlineEvidence: run.offlineEvidence,
935							servedStatic: run.servedStatic,
936							observerFinalization: run.observerFinalization,
937							successfulNonLoopback: run.successfulNonLoopback,
938						}),
939					)
940			)
941				throw new Error(`Witness real-app run differs: ${key}`);
942			const pair = `${run.app}:${run.lane}`;
943			const prior = semanticPasses.get(pair);
944			if (prior !== undefined && prior !== run.semanticDigest)
945				throw new Error(`Witness real-app repeated pass differs: ${pair}`);
946			semanticPasses.set(pair, run.semanticDigest);
947			for (const interaction of run.interactions) {
948				gestures.add(interaction.kind);
949			}
950		}
951		if (
952			expected.size !== 0 ||
953			[...gestures].sort().join(',') !== 'click,drag,hover,press,scroll,type'
954		)
955			throw new Error('Witness real-app interaction coverage differs');
956		if (
957			receipt.mutations?.length !== 2 ||
958			receipt.mutations.some(
959				(mutation) =>
960					mutation.failure !== 'witness-semantic-assertion' ||
961					mutation.intendedFailure !== true ||
962					mutation.restoredByteIdentically !== true,
963			) ||
964			!receipt.mutations.some((mutation) => mutation.app === 'react-boilerplate') ||
965			!receipt.mutations.some((mutation) => mutation.app === 'angular-realworld') ||
966			receipt.killedByGoogleInventory?.transformEdits !== 3 ||
967			receipt.locality?.mode !== 'offline' ||
968			receipt.locality?.successfulNonLoopback !== 0 ||
969			receipt.locality?.osWideIsolation !== false ||
970			!receipt.nonclaims?.some((claim) => claim.includes('Drag is tested only')) ||
971			receipt.integrity?.algorithm !== 'sha256' ||
972			receipt.integrity.canonicalDigest !== witnessRealAppDigest(receipt)
973		)
974			throw new Error('Witness real-app receipt integrity or nonclaims differ');
975		return receipt;
976	}
