1	/**
2	 * The Super Productivity Witness calibration driver.
3	 *
4	 * There is no published journey for this application yet, and pinning one
5	 * before the live DOM has been read is what the TinyTranslator rounds spent
6	 * four passes undoing. This drives ONE lane of the bound production-static
7	 * output through the same host the proof will use, asks the page a list of
8	 * candidate questions, and prints every answer — including the refusals, which
9	 * are the measurement when a candidate is wrong.
10	 *
11	 * It publishes nothing, asserts nothing of its own, and is not part of any
12	 * receipt. Its only output is stdout.
13	 */
14	
15	import { readFileSync } from 'node:fs';
16	import { basename, join, resolve } from 'pathe';
17	import { box, runBoxes } from '@async/witness';
18	import { joinURL } from 'ufo';
19	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
20	import { WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES } from '../../../core/src/receipts/witness-angular-super-productivity.ts';
21	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
22	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
23	import { startStaticServer } from '../witness/real-app-run.ts';
24	
25	const root = resolve(import.meta.dirname, '../../../..');
26	
27	/**
28	 * The two bound lanes, exactly as the schema names them: the era lane is the
29	 * retained tree the u21 digest correction was recomputed from, and the migrated
30	 * lane is the offline-faithful rebuild u23 published.
31	 */
32	const laneRoots = {
33		baseline: join(
34			root,
35			'.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
36		),
37		migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-23'),
38	} as const;
39	
40	const VIEWPORT = { width: 1280, height: 900 } as const;
41	
42	/**
43	 * The route the driver deep-links to.
44	 *
45	 * The bare document was measured first and records its navigation as `#/`,
46	 * which is not one of the nine routes the application declares — the router
47	 * renders the work view for it through the wildcard, and a recorded `#/` would
48	 * be a navigation the application did not name. Deep-linking the declared route
49	 * is what makes the recorded navigation a declared one.
50	 */
51	const INITIAL_ROUTE = '/#/work-view';
52	
53	/**
54	 * The candidate selectors, read out of the application's own templates rather
55	 * than guessed: the shell, the work view, the add-task surface, the task list
56	 * and the two controls the time-tracking and theme legs would be anchored on.
57	 * Each is asked for as a count, so a candidate that does not resolve reports
58	 * zero rather than ending the pass.
59	 */
60	const CANDIDATES = [
61		'main-header',
62		'main-header .project-settings-btn',
63		'mat-drawer-container',
64		'side-nav',
65		// Corrected in the u20c2a round. The first calibration pass asked for
66		// `work-view-page` because that is what the component's FILE is called; the
67		// component's own `selector` is `work-view`, and the earlier pass measured
68		// the mistake honestly as zero. The wrong spelling is kept beside the right
69		// one so the correction stays visible in the driver rather than only in a
70		// note: a reader can see both asked, and the counts say which one the
71		// application actually renders.
72		'work-view-page',
73		'work-view',
74		'.work-view-header',
75		'add-task-bar',
76		'add-task-bar input',
77		'task-list',
78		'task-list task',
79		'task',
80		'task .title',
81		'task .play-btn',
82		'task .drag-handle',
83		'.task-list-wrapper',
84		'.completed-tasks-heading',
85		'backlog',
86		'split',
87		'banner',
88		'mat-progress-bar',
89	] as const;
90	
91	/**
92	 * The observed page record out of the box receipt, narrowed to the four things
93	 * an exact inventory has to be pinned from: what the console said, what the
94	 * browser failed to fetch, what the page threw, and where it navigated.
95	 */
96	function pageSummary(receiptPath: string): unknown {
97		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
98			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
99		};
100		const page = receipt.boxes?.[0]?.pages?.[0];
101		if (page === undefined) return null;
102		return {
103			consoleMessages: page.consoleMessages,
104			pageErrors: page.pageErrors,
105			failedRequests: page.failedRequests,
106			navigations: page.navigations,
107		};
108	}
109	
110	export async function calibrateAngularSuperProductivityLane(
111		lane: 'baseline' | 'migrated',
112	): Promise<void> {
113		const laneRoot = laneRoots[lane];
114		const receiptDir = join(
115			root,
116			'.versionless/stage/witness-angular-super-productivity-calibrate',
117			lane,
118		);
119		const staticServer = await startStaticServer(laneRoot, { profile: 'current-witness' });
120		const host = createPlaywrightWitnessHost({
